S.append(CR(c,B+' · 4','E ~ F: anh em phía sau',"em ~ strong {color: red;}\n\n<p>Do <em>Håkon</em>, làm với\n <strong>Tim</strong> tại\n <strong>CERN</strong>.</p>",'<p style="font-size:23px;margin:0">Do <em>Håkon</em>, làm với <strong style="color:red">Tim</strong> tại <strong style="color:red">CERN</strong>.</p><div style="font-size:20px;margin-top:8px">Cả <b style="color:#000">hai strong</b> đều nằm sau em nên đều đỏ (Hình 15.7).</div>',KEY('<b>~</b> không cần liên tục: mọi F cùng cha, đứng <b>sau</b> E.'),21))
