S.append(CR(c,B+' · 5','Thực hành: Lợi ích của CSS (HTML)','<h1>LỢI ÍCH CỦA CSS</h1>\n<p>Sử dụng CSS mang lại … </p>\n<ul>\n <li><strong>Trình bày chính xác.</strong>\n   Có thể điều khiển <em>chính xác</em>…</li>\n <li><strong>Tiết kiệm công sức.</strong>\n   …</li>\n <li><strong>Điều khiển hiển thị đa dạng.</strong>\n   …</li>\n <li><strong>Tiếp cận theo ngữ nghĩa.</strong>\n   …</li>\n</ul>','<div style="font-size:22px"><b style="color:#000">Bước 1: dựng HTML</b><ul><li>Bốn ý chính: cặp thẻ <b style="color:#000">ul, li</b>.</li><li>Câu đầu in đậm: thẻ <b style="color:#000">strong</b>.</li><li>Cụm từ in nghiêng: thẻ <b style="color:#000">em</b>.</li></ul></div>',KEY('Đặt nội dung bằng HTML trước; định dạng bằng CSS sau (tách hai việc).'),17))
