S.append(S2(c,'TRỌNG TÂM','Những điều phải nhớ',card('Ghi nhớ',ul(['RGB: 3 giá trị 0–255; <b>2²⁴ = 16 777 216</b> màu; mã <b>#rrggbb</b>.','HSL: Hue 0–360°, Saturation, Lightness; <b>L=50%</b> màu đúng.','Xám: <b>r=g=b</b> hoặc <b>S=0%</b>. CSS3 có <b>140</b> tên màu.','<b>color, background-color, border</b>; border <b>không kế thừa</b>.','Tổ hợp: <b>E F</b> (cháu), <b>E&gt;F</b> (con), <b>E+F</b> (liền kề), <b>E~F</b> (sau).'],6)),T(tr('Muốn chọn…','Viết',h=True)+tr('Mọi p trong div','div p',m=True)+tr('em là con của p','p > em',m=True)+tr('strong ngay sau em','em + strong',m=True)+tr('mọi strong sau em','em ~ strong',m=True))))
